export const purchaseChart=(labels,id,role,values,texts,prefer='higher')=>{
 const chart=projectionChart(id,role,values,texts,prefer);
 ['en-US','es-MX','pt-BR'].forEach((locale,index)=>{chart.copy[locale].data.series[0].label=labels[index];});
 return chart;
};
